<script setup>import{Link,useForm}from'@inertiajs/vue3';const form=useForm({email:'',password:'',remember:false});</script><template><div class="flex min-h-screen items-center justify-center bg-slate-950 p-4"><form class="w-full max-w-sm rounded-[10px] bg-white p-6" @submit.prevent="form.post('/login')"><img src="/assets/prinx-logo.svg" class="h-10"><h1 class="mt-6 text-2xl font-black">Sign in</h1><div class="mt-5 grid gap-4"><div><label class="label">Email</label><input v-model="form.email" type="email" class="input"><p class="error">{{form.errors.email}}</p></div><div><label class="label">Password</label><input v-model="form.password" type="password" class="input"></div><label class="flex gap-2 text-sm"><input v-model="form.remember" type="checkbox"> Remember me</label><button class="btn-primary" :disabled="form.processing">Sign in</button></div><p class="mt-5 text-sm text-slate-500">No account? <Link href="/register" class="font-bold text-prinx-600">Create one</Link></p></form></div></template>
